import{z as n,x as s,o as e,c as i,q as o,j as B,D as a,d as A,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"弹性伸缩","description":"","frontmatter":{"title":"弹性伸缩","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-autoscaling.md","filePath":"llm/sch-autoscaling.md","lastUpdated":1791063341000}'),d={name:"llm/sch-autoscaling.md"};function D(C,E,p,g,c,h){const t=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=o('<h1 id="弹性伸缩" tabindex="-1">弹性伸缩 <a class="header-anchor" href="#弹性伸缩" aria-label="Permalink to &quot;弹性伸缩&quot;">​</a></h1><div class="epigraph"><p>副本不是 30 秒就位的无状态容器：权重加载以分钟计，排干以输出长度计；伸缩的正确信号是 goodput 赤字，不是利用率。</p><footer>—— 据 Zhong et al., OSDI 2024 的 goodput 口径与前缀感知扩缩容的工程实践整理</footer></div><p><a href="/llm/sch-overload-degradation">上一课</a>用三道闸在容量不足时保护存量；本课写容量本身怎么跟上流量。无状态服务的扩缩容直觉在这里处处失灵：副本有状态（KV 与路由亲和）、冷启动重、缩容要排干在途生成。前缀感知的扩缩已有专文（<a href="/llm/prefix-aware-autoscaling">前缀感知扩缩容</a>），本课写完整闭环：信号、供给、排干、冷启动的预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个失灵。<strong>信号失灵</strong>：GPU 利用率到 80% 时 goodput 可能已经在掉——本步 token 预算被 prefill 吃满、ITL 合同破了，利用率还在涨；<span class="marginnote">术语翻译：goodput 就是「达标的好产出」——只统计同时满足 TTFT、ITL 等延迟合同的完成请求，违约的完成不算数；goodput 赤字就是承诺速率减去这个达标速率。用它当伸缩信号，等于直接盯「客户拿到了多少合格服务」，而不是盯机器有多忙。</span>裸队列长度也不含服务时间的变化，长提示为主的时段，同样的队列深度意味着长得多的等待。<strong>供给失灵</strong>：新副本不是加一台空机，要进程启动、权重从存储加载、CUDA 图捕获、首 token 预热，分钟级；多卡副本要整组到齐（gang）。<strong>退出失灵</strong>：缩容不能杀进程了事，在途 decode 少则几十秒、多则几分钟（由输出上界决定），杀掉就是违约。</p><h3 id="信号、供给与排干" tabindex="-1">信号、供给与排干 <a class="header-anchor" href="#信号、供给与排干" aria-label="Permalink to &quot;信号、供给与排干&quot;">​</a></h3><p>信号组：等待队列深度乘单步期望服务时间（Little 定律反推 TTFT 走向）、KV 水位、goodput 赤字（承诺速率减实际达标速率），取最先越线者触发。供给分两路：<strong>预测</strong>（日周期流量提前开暖池，夜间闲置由批处理层回填）与<strong>反应</strong>（突发靠准入缓冲撑过启动窗口）。新副本的放置按组合算：PD 配比按当前负载重算（<a href="/llm/sch-pd-disaggregated">PD 分离的调度</a> 的公式），多卡 gang 整组分配。扩入与扩出对称相反：先停准入 → 在途排干（等自然结束，或按 <a href="/llm/sch-preemption-migration">抢占与请求迁移</a> 把请求迁到存留副本再停）→ 热前缀按叶先根后回收。</p>',7)),(e(),B(r,null,{default:a(()=>[l(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E4%BF%A1%E5%8F%B7%EF%BC%9A%E9%98%9F%E5%88%97%E4%B9%98%E6%9C%8D%E5%8A%A1%E6%97%B6%E9%97%B4%20%2F%20KV%20%E6%B0%B4%E4%BD%8D%20%2F%20goodput%20%E8%B5%A4%E5%AD%97%22%5D%20--%3E%20DEC%7B%22%E8%B6%8A%E7%BA%BF%22%7D%0A%20%20DEC%20--%3E%7C%E6%89%A9%7C%20PRED%5B%22%E9%A2%84%E6%B5%8B%E5%B1%82%E5%BC%80%E6%9A%96%E6%B1%A0%EF%BC%8C%E5%8F%8D%E5%BA%94%E5%B1%82%E8%A1%A5%E7%AA%81%E5%8F%91%22%5D%0A%20%20PRED%20--%3E%20PROV%5B%22%E4%BE%9B%E7%BB%99%EF%BC%9A%E8%BD%BD%E6%9D%83%E9%87%8D%EF%BC%8C%E6%8D%95%E5%9B%BE%EF%BC%8C%E9%A2%84%E7%83%AD%E9%A6%96%20token%22%5D%0A%20%20PROV%20--%3E%20COPY%5B%22%E5%A4%8D%E5%88%B6%E7%83%AD%E5%89%8D%E7%BC%80%EF%BC%8C%E5%8A%A0%E5%85%A5%E8%B7%AF%E7%94%B1%E6%B1%A0%22%5D%0A%20%20COPY%20--%3E%20POOL%5B%22%E6%9C%8D%E5%8A%A1%E6%B1%A0%22%5D%0A%20%20DEC%20--%3E%7C%E7%BC%A9%7C%20ADM%5B%22%E5%85%88%E5%81%9C%E5%87%86%E5%85%A5%22%5D%0A%20%20ADM%20--%3E%20DRAIN%5B%22%E6%8E%92%E5%B9%B2%EF%BC%9A%E7%AD%89%E7%BB%93%E6%9D%9F%E6%88%96%E8%BF%81%E7%A7%BB%E5%9C%A8%E9%80%94%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DRAIN%20--%3E%20REL%5B%22%E6%8C%89%E5%8F%B6%E5%85%88%E6%A0%B9%E5%90%8E%E5%9B%9E%E6%94%B6%EF%BC%8C%E9%87%8A%E6%94%BE%E5%89%AF%E6%9C%AC%22%5D%0A%20%20REL%20--%3E%20POOL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>闭环拆段加预算核算</strong>：把伸缩拆成信号、供给、排干三段，逐段替换无状态服务的失灵直觉——信号换成 goodput 赤字、队列乘服务时间、KV 水位，取最先越线者触发；供给按权重加载、图捕获、首 token 预热三段冷启动预算核算，暖池按流量方差定价而非均值；<span class="marginnote">直觉类比：暖池就像餐馆在饭点前先备好的半成品菜——平时看是闲置成本，客人一进门就能立刻上菜。按方差备货而不是按均值备货，正是「宁可备多一点，也别让高峰时段的客人在门口等上一分钟」。</span>排干复用抢占课的代价账，在「等结束」与「迁移」之间选。预测与反应两路按「伸缩时延与流量翻倍时间的赛跑」取舍。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冷启动是三段预算：权重加载（存储带宽决定，分钟里的最大头）、图捕获与编译（秒到十秒级）、首 token 预热（分配器与页表的冷路径）。暖池大小按「流量方差加启动窗口」定价：多留一台是空转卡时，少留一台是分钟级违约——按方差算，不按均值算。伸缩决策时延与流量翻倍时间的赛跑决定预测是不是必需品：流量 5 分钟翻倍而副本 6 分钟就位，纯反应式永远追不上，准入缓冲（上一课）负责把这段窗口垫过去。缩容的排干上界是 <code>max_tokens</code> 上限乘步时延，这个数决定「等结束」是否可接受；不可接受就付迁移的钱——取舍就是抢占课的三本账。<span class="marginnote">数字实例：设 <code>max_tokens</code> = 2048、decode 每步 20 ms，最坏情况一个请求要 2048 × 20 ms ≈ 41 秒才能自然结束；如果你的缩容窗口只允许 30 秒，那「等结束」这条路直接出局，只能走迁移。</span></p>',4)),(e(),B(r,null,{default:a(()=>[l(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E7%BC%A9%E6%8E%89%E4%B8%80%E4%B8%AA%E5%89%AF%E6%9C%AC%22%5D%20--%3E%20A%5B%22%E5%85%88%E5%81%9C%E5%87%86%E5%85%A5%EF%BC%9A%E4%B8%8D%E5%86%8D%E6%8E%A5%E6%96%B0%E8%AF%B7%E6%B1%82%22%5D%0A%20%20A%20--%3E%20B%7B%22%E6%9C%80%E5%9D%8F%E6%8E%92%E5%B9%B2%20%3D%20max_tokens%20%C3%97%20%E6%AD%A5%E6%97%B6%E5%BB%B6%EF%BC%8C%E7%AD%89%E5%BE%97%E8%B5%B7%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E7%AD%89%E5%BE%97%E8%B5%B7%22%7C%20C%5B%22%E5%9C%A8%E9%80%94%E8%AF%B7%E6%B1%82%E8%87%AA%E7%84%B6%E7%BB%93%E6%9D%9F%22%5D%0A%20%20B%20--%3E%7C%22%E7%AD%89%E4%B8%8D%E8%B5%B7%22%7C%20D%5B%22%E6%8A%8A%E5%9C%A8%E9%80%94%E8%AF%B7%E6%B1%82%E8%BF%81%E5%88%B0%E5%AD%98%E7%95%99%E5%89%AF%E6%9C%AC%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%A4%8D%E5%88%B6%E5%AF%B9%E5%BA%94%E7%83%AD%E5%89%8D%E7%BC%80%E5%88%B0%E6%8E%A5%E6%94%B6%E6%96%B9%22%5D%0A%20%20C%20--%3E%20E%5B%22%E9%87%8A%E6%94%BE%E5%89%AF%E6%9C%AC%22%5D%0A%20%20F%20--%3E%20E%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=o('<p><span class="marginnote">权重加载账：70B 模型 fp16 约 140 GB，NVMe 顺序读按 3.5 GB/s 算约 40 s，加上图捕获与预热，冷启动 1–2 分钟；还没算多卡副本必须整组到齐的 gang 等待。scale-to-zero 只对可容忍分钟级首 token 的层成立，交互层永远留暖池。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>伸缩的粒度受架构约束：TP 组整组伸缩，PD 两池独立伸缩但配比联动；跨区弹性受数据驻留与配额限制（<a href="/llm/multi-region-failover">多区域故障转移</a>）。预测模型会失效：营销活动、爆款应用的流量形态跳变，预测错了要靠准入缓冲与降级阶梯兜底——三课是同一个系统。缩容与故障处理共享排干机制：节点故障时在途请求的处置（迁移或重算）与计划内缩容是同一套代码，分开写就会只测过一条路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号用 goodput 赤字、队列乘服务时间、KV 水位；利用率与裸队列都会说谎。</li><li>供给是分钟级三段：权重、图、预热；预测开暖池，反应靠准入缓冲垫窗口。</li><li>扩容单位是组合（PD 配比、gang 组），不是一台机器。</li><li>排干先停准入，再等结束或迁移；上界是输出上限乘步时延。</li><li>暖池按流量方差定价；scale-to-zero 只属于容忍分钟级延迟的层。</li><li>出处：goodput 口径见 Zhong et al., OSDI 2024；前缀复制见站内前缀感知扩缩容专文，余按工程实践整理。</li></ul>',5))])}const u=n(d,[["render",D]]);export{_ as __pageData,u as default};
